INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63565282', 63565282, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PENANGGULANGAN KEBAKARAN DAN PENYELAMATAN', 'Pengelolaan Data dan Informasi (Analis Data) Tahap 2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 61050000, 'June 2026', 'APBD', 1, 1, '1 Orang X 6 Bulan', '1. Manajemen Data (Mengumpulkan, menyimpan, membersihkan dan mengintegrasikan data) dari internal dan eksternal Disgulkarmat untuk kebutuhan analisis data. 2. Analisis Data (Menganalisis data menggunakan alat statistik dan teknik analisis lainnya untuk menemukan pola, tren, dan hubungan yang bermanfaat). 3. Visualisasi data (menyajikan data secara visual menggunakan teknik secara efektif meliputi grafik, diagram dan visualisasi interaktif untuk mengkomunikasikan wawasan dan tren). 4. Pembuatan Laporan hasil analisis (Membuat Laporan berdasarkan hasil analisis dan saran rekomendasi yang dapat diimplementasikan untuk meningkatkan kinerja Disgulkarmat). 5. Menyusun jadwal review (Menyusun jadwal review pekerjaan dan melaporkan progress pelaksanaan kegiatan analisis data) 6. Menjaga Privasi dan Keamanan Data Disgulkarmat. 7. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan. 8. Melaporkan dan mempertanggung jawabkan pelaksanaan tugas.', '1. Pendidikan minimal Strata 1 (S1) Jurusan Ilmu Statistik/ Matematika dan lain-lain; 2. Melampirkan Daftar Riwayat Hidup/Curriculum Vitae (CV); 3. Melampirkan Ijazah, Transkip Nilai; 4. Melampirkan pengalaman kerja / kontrak kerja; 5. Mampu berkomunikasi dengan baik dan bekerja di bawah tekanan; 6. Memiliki komitmen dan minat dalam bidang kebakaran, jiwa kemanusiaan, semangat pengabdian dan dedikasi tinggi; 7. Mampu bekerja secara mandiri dan dapat bekerjasama dalam kelompok; 8. Melampirkan Surat Keterangan Sehat Jasmani dan Rohani dari RSUD, RSUP, Puskesmas Kelurahan/Kecamatan (dilampirkan pada saat dinyatakan lulus dan/atau penandatanganan kontrak); 9. Melampirkan Surat Pernyataan tidak menuntut untuk diangkat sebagai calon PNS dan/atau PPPK, tidak menuntut apabila proses rekrutmen dibatalkan karena ketentuan dan keputusan yang ada, bersedia menerima upah sesuai dengan yang tertuang dalam Dokumen Pelaksanaan Anggaran/ DPA, (Format Terlampir). 10. Pengalaman minimal 3 (tiga) tahun sebagai Data Analyst/ Data Scientist / Data Enginering/ Data Manager pada bidang pekerjaan sejenis. 11. Memiliki pemahaman yang baik tentang manajemen data, analisis statistik, dan visualisasi data. 12. Memiliki pengetahuan yang baik tentang teknik-teknik statistic, data mining, dan pemodelan prediktif. 13. Menguasai Microsoft Office (pengolahan data pada excel). 14. Menguasai data visualization dan analytics tools seperti: Goggle Analytic/ Semrush/ Google Data Studio/ Phyton/ R/ SQL/ GIS/ Tableau dan sejenisnya. 15. Menguasai teknis pelaporan hasil analisis data. 16. Kemampuan komunikasi yang baik untuk menjelaskan hasil analisa data secara jelas dan ringkas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1010370);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63524318', 63524318, 'analyze_legacy', 'Kab. Bangkalan', 'kabkota', 'DINAS PENANAMAN MODAL DAN PELAYANAN TERPADU SATU PINTU', 'Tiket Pesawat - Bisnis (PP)', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Timur, Bangkalan (Kab.)', 16398000, 'January 2026', 'APBD', 1, 1, '3 Orang / Kali', 'Tiket Pesawat - Bisnis (PP);', 'JAKARTA - SURABAYA;', 16398000, 'absurd', 'Pengadaan tiket pesawat kelas bisnis untuk perjalanan dinas domestik menimbulkan indikasi kuat penggunaan anggaran yang tidak hemat dan berpotensi memicu kecemburuan sosial. Untuk rute domestik singkat, kelas bisnis umumnya tidak esensial bagi pelaksanaan tugas layanan perizinan.', NULL, NULL, 4, 1, 1, 1, 1, 1010371);
