INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63581940', 63581940, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Isi Tabung Gas Medis', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 3015732425, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Belanja isi tabung gas medis/oksigen merupakan kegiatan pengadaan pengisian ulang gas medis untuk menunjang pelayanan kesehatan di RSUD Kota Banjar. Kegiatan ini bertujuan untuk menjamin ketersediaan gas medis/oksigen yang aman, bermutu, dan sesuai standar pelayanan rumah sakit guna mendukung pelayanan rawat jalan, rawat inap, gawat darurat, dan pelayanan penunjang secara berkesinambungan.', 'Pengisian ulang tabung gas medis/oksigen untuk mendukung pelayanan rawat jalan, rawat inap, gawat darurat, dan penunjang di RSUD Kota Banjar. Gas medis/oksigen yang disediakan harus memenuhi standar mutu dan keselamatan serta ketentuan teknis gas medis. Pelaksanaan pengadaan didasarkan pada perencanaan kebutuhan pelayanan rumah sakit. Proses pengisian, pengangkutan, dan penyerahan tabung dilakukan sesuai standar keselamatan dan peraturan yang berlaku. Kegiatan ini bertujuan menjamin ketersediaan gas medis/oksigen yang aman, bermutu, dan berkesinambungan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1011331);
